css:
.container {
  width: 100%;
  height: 100%;
  /* Add your background pattern here */
  background-color: #e5e5f7;
  opacity: 0.7;
  background:
    radial-gradient(
      circle,
      transparent 20%,
      #e5e5f7 20%,
      #e5e5f7 80%,
      transparent 80%,
      transparent
    ),
    radial-gradient(
        circle,
        transparent 20%,
        #e5e5f7 20%,
        #e5e5f7 80%,
        transparent 80%,
        transparent
      )
      12.5px 12.5px,
    linear-gradient(#3784c5 1px, transparent 1px) 0 -0.5px,
    linear-gradient(90deg, #3784c5 1px, #e5e5f7 1px) -0.5px 0;
  background-size:
    25px 25px,
    25px 25px,
    12.5px 12.5px,
    12.5px 12.5px;
}
